Exercise: Piecing It Together (piecing-it-together)
Difficulty: 6/9

Instructions:
# Instructions

Given partial information about a jigsaw puzzle, add the missing pieces.

If the information is insufficient to complete the details, or if given parts are in contradiction, the user should be notified.

The full information about the jigsaw puzzle contains the following parts:

- `pieces`: Total number of pieces
- `border`: Number of border pieces
- `inside`: Number of inside (non-border) pieces
- `rows`: Number of rows
- `columns`: Number of columns
- `aspectRatio`: Aspect ratio of columns to rows
- `format`: Puzzle format, which can be `portrait`, `square`, or `landscape`

For this exercise, you may assume square pieces, so that the format can be derived from the aspect ratio:

- If the aspect ratio is less than 1, it's `portrait`
- If it is equal to 1, it's `square`
- If it is greater than 1, it's `landscape`

## Three examples

### Portrait

A portrait jigsaw puzzle with 6 pieces, all of which are border pieces and none are inside pieces.
It has 2 columns and 3 rows.
The aspect ratio is 0.666666... (2/3).

![A 2 by 3 jigsaw puzzle](https://assets.exercism.org/images/exercises/piecing-it-together/jigsaw-puzzle-2x3.svg)

### Square

A square jigsaw puzzle with 9 pieces, all of which are border pieces except for the one in the center, which is an inside piece.
It has 3 columns and 3 rows.
The aspect ratio is 1.0 (3/3).

![A 3 by 3 jigsaw puzzle](https://assets.exercism.org/images/exercises/piecing-it-together/jigsaw-puzzle-3x3.svg)

### Landscape

A landscape jigsaw puzzle with 12 pieces, 10 of which are border pieces and 2 are inside pieces.
It has 4 columns and 3 rows.
The aspect ratio is 1.333333... (4/3).

![A 4 by 3 jigsaw puzzle](https://assets.exercism.org/images/exercises/piecing-it-together/jigsaw-puzzle-4x3.svg)


Starter file:
```zig
pub const PuzzleError = error{
    InsufficientData,
    ContradictoryData,
};

pub const Format = enum {
    portrait,
    square,
    landscape,
};

pub const PartialInformation = struct {
    pieces: ?u30 = null, //
    border: ?u30 = null, //
    inside: ?u30 = null, //
    rows: ?u30 = null, //
    columns: ?u30 = null, //
    aspectRatio: ?f64 = null, //
    format: ?Format = null, //
};

pub const FullInformation = struct {
    pieces: u30, //
    border: u30, //
    inside: u30, //
    rows: u30, //
    columns: u30, //
    aspectRatio: f64, //
    format: Format, //
};

pub fn jigsawData(puzzle: PartialInformation) PuzzleError!FullInformation {
    _ = puzzle;
    @compileError("please implement the jigsawData function");
}

```

Tests that will be run with `zig test`:
```zig
const std = @import("std");
const testing = std.testing;

const piecing_it_together = @import("piecing_it_together.zig");
const jigsawData = piecing_it_together.jigsawData;
const PuzzleError = piecing_it_together.PuzzleError;
const Format = piecing_it_together.Format;
const PartialInformation = piecing_it_together.PartialInformation;
const FullInformation = piecing_it_together.FullInformation;

test "1000 pieces puzzle with 1.6 aspect ratio" {
    const puzzle = PartialInformation{
        .pieces = 1000,
        .aspectRatio = 1.6,
    };
    const expected = FullInformation{
        .pieces = 1000,
        .border = 126,
        .inside = 874,
        .rows = 25,
        .columns = 40,
        .aspectRatio = 1.6,
        .format = .landscape,
    };
    const actual = try jigsawData(puzzle);
    try testing.expectEqual(expected, actual);
}

test "square puzzle with 32 rows" {
    const puzzle = PartialInformation{
        .rows = 32,
        .format = .square,
    };
    const expected = FullInformation{
        .pieces = 1024,
        .border = 124,
        .inside = 900,
        .rows = 32,
        .columns = 32,
        .aspectRatio = 1.0,
        .format = .square,
    };
    const actual = try jigsawData(puzzle);
    try testing.expectEqual(expected, actual);
}

test "400 pieces square puzzle with only inside pieces and aspect ratio" {
    const puzzle = PartialInformation{
        .inside = 324,
        .aspectRatio = 1.0,
    };
    const expected = FullInformation{
        .pieces = 400,
        .border = 76,
        .inside = 324,
        .rows = 20,
        .columns = 20,
        .aspectRatio = 1.0,
        .format = .square,
    };
    const actual = try jigsawData(puzzle);
    try testing.expectEqual(expected, actual);
}

test "1500 pieces landscape puzzle with 30 rows and 1.6 aspect ratio" {
    const puzzle = PartialInformation{
        .rows = 30,
        .aspectRatio = 1.6666666666666667,
    };
    const expected = FullInformation{
        .pieces = 1500,
        .border = 156,
        .inside = 1344,
        .rows = 30,
        .columns = 50,
        .aspectRatio = 1.6666666666666667,
        .format = .landscape,
    };
    const actual = try jigsawData(puzzle);
    try testing.expectEqual(expected, actual);
}

test "300 pieces portrait puzzle with 70 border pieces" {
    const puzzle = PartialInformation{
        .pieces = 300,
        .border = 70,
        .format = .portrait,
    };
    const expected = FullInformation{
        .pieces = 300,
        .border = 70,
        .inside = 230,
        .rows = 25,
        .columns = 12,
        .aspectRatio = 0.48,
        .format = .portrait,
    };
    const actual = try jigsawData(puzzle);
    try testing.expectEqual(expected, actual);
}

test "puzzle with insufficient data" {
    const puzzle = PartialInformation{
        .pieces = 1500,
        .format = .landscape,
    };
    const actual = jigsawData(puzzle);
    try testing.expectError(PuzzleError.InsufficientData, actual);
}

test "puzzle with contradictory data" {
    const puzzle = PartialInformation{
        .rows = 100,
        .columns = 1000,
        .format = .square,
    };
    const actual = jigsawData(puzzle);
    try testing.expectError(PuzzleError.ContradictoryData, actual);
}

test "very large landscape" {
    const puzzle = PartialInformation{
        .border = 1216,
        .inside = 86625,
        .format = .landscape,
    };
    const expected = FullInformation{
        .pieces = 87841,
        .border = 1216,
        .inside = 86625,
        .rows = 233,
        .columns = 377,
        .aspectRatio = 1.6180257510729614,
        .format = .landscape,
    };
    const actual = try jigsawData(puzzle);
    try testing.expectEqual(expected, actual);
}

```
